//! Q7-4 gate, harness-less (QEMU bridge plan Q7-4): GLES2 proxy calls from an arm64 guest under QEMU carry fp arguments, a ninth (stack) argument and an fp result through the binding route, bit for bit.
//! Each GL entry point is looked up in the QEMU binding table (`bindings::rows`, generated by build.rs from the GLES prototypes): its row must be a Generic binding of libGLESv2.so, and its result class is the one the gate binds a host recorder with (`qemu::bind_result`). The recorder has the Khronos prototype and stands in for the host GL front (the table resolves the front from SYSTEM_LIB, which a harness-less run has not got; `xtask test gl-proxies` gates that resolution). The fixture (`xtask/testdata/qemu-gl/fixture.c`, static) calls each through the NDK header's PFN type, so the arguments are where NDK clang puts them for that prototype.
//! Env (xtask qemu_gl.rs sets it; unset prints SKIP): ATL_ENGINE_SO (the engine `.so`), ATL_QEMU_GL_FIXTURE (fixture.c, built static).
//! Expected values are the fixture's literals, written out here again (never read from the engine); GL enum values from gl2.h / gl2ext.h.
//! Checks: (s) started; (b) every GL name below is a Generic row of libGLESv2.so whose result class is its prototype's (void, glGetPathLengthNV GLfloat); (c) glClearColor; (u) glUniform4f; (d) glDepthRangef; (t) glTexParameterf; (a) glVertexAttrib4f; (i) glTexImage2D, 9 arguments, pixels the guest's first stack word; (j) glTexSubImage2D, likewise; (k) glCompressedTexImage2D, 8 arguments; (n) glGetPathLengthNV's arguments, and the guest got [`PATH_LENGTH`]'s bits back.
//! Output: `qemu-gl: (x) ok` per check, `(x) FAIL <why>` otherwise, exit 0 when all pass.
#![allow(clippy::print_stdout, reason = "test harness output is its verdict")]

use std::path::Path;
use std::process::ExitCode;
use std::sync::Mutex;
use std::sync::atomic::{AtomicU64, Ordering};

use atl_native_bridge::engine::bindings::{Binding, Host, rows};
use atl_native_bridge::engine::jni::Class;
use atl_native_bridge::engine::{self, qemu};

/// The guest library of the GLES2 proxies.
const SONAME: &str = "libGLESv2.so";

/// gl2.h / gl2ext.h enum values the fixture passes.
const GL_TEXTURE_2D: u32 = 0x0DE1;
const GL_TEXTURE_MIN_FILTER: u32 = 0x2801;
const GL_LINEAR: u32 = 0x2601;
const GL_RGBA: u32 = 0x1908;
const GL_RGB: u32 = 0x1907;
const GL_UNSIGNED_BYTE: u32 = 0x1401;
const GL_UNSIGNED_SHORT_5_6_5: u32 = 0x8363;
const GL_ETC1_RGB8_OES: u32 = 0x8D64;
/// fixture.c TEX_PIXELS, SUB_PIXELS, ETC_DATA: pointer values, never dereferenced.
const TEX_PIXELS: u64 = 0x0000_7e57_1234_5670;
const SUB_PIXELS: u64 = 0x0000_5ab5_0000_9ab0;
const ETC_DATA: u64 = 0x0000_ec10_00c0_ffe0;
/// The recorder's glGetPathLengthNV answer: exact in a float, no input value, so only the fp result lane can carry it.
const PATH_LENGTH: f32 = 12.375;

/// One argument word as the recorder saw it: an integer sign- or zero-extended by its C type, a float's 32 bits.
fn uint(v: u32) -> u64 {
    u64::from(v)
}
fn int(v: i32) -> u64 {
    i64::from(v) as u64
}
fn float(v: f32) -> u64 {
    u64::from(v.to_bits())
}

/// The arguments of the last recorder call.
static SEEN: Mutex<Vec<u64>> = Mutex::new(Vec::new());
fn record(words: Vec<u64>) {
    *SEEN.lock().expect("seen") = words;
}

// the recorders: each has its gl2.h / gl2ext.h prototype
extern "C" fn gl_clear_color(r: f32, g: f32, b: f32, a: f32) {
    record(vec![float(r), float(g), float(b), float(a)]);
}
extern "C" fn gl_uniform4f(loc: i32, x: f32, y: f32, z: f32, w: f32) {
    record(vec![int(loc), float(x), float(y), float(z), float(w)]);
}
extern "C" fn gl_depth_rangef(n: f32, f: f32) {
    record(vec![float(n), float(f)]);
}
extern "C" fn gl_tex_parameterf(target: u32, pname: u32, param: f32) {
    record(vec![uint(target), uint(pname), float(param)]);
}
extern "C" fn gl_vertex_attrib4f(index: u32, x: f32, y: f32, z: f32, w: f32) {
    record(vec![uint(index), float(x), float(y), float(z), float(w)]);
}
#[expect(clippy::too_many_arguments, reason = "glTexImage2D's prototype")]
extern "C" fn gl_tex_image_2d(
    target: u32,
    level: i32,
    internal: i32,
    width: i32,
    height: i32,
    border: i32,
    format: u32,
    ty: u32,
    pixels: usize,
) {
    record(vec![
        uint(target),
        int(level),
        int(internal),
        int(width),
        int(height),
        int(border),
        uint(format),
        uint(ty),
        pixels as u64,
    ]);
}
#[expect(clippy::too_many_arguments, reason = "glTexSubImage2D's prototype")]
extern "C" fn gl_tex_sub_image_2d(
    target: u32,
    level: i32,
    x: i32,
    y: i32,
    width: i32,
    height: i32,
    format: u32,
    ty: u32,
    pixels: usize,
) {
    record(vec![
        uint(target),
        int(level),
        int(x),
        int(y),
        int(width),
        int(height),
        uint(format),
        uint(ty),
        pixels as u64,
    ]);
}
#[expect(
    clippy::too_many_arguments,
    reason = "glCompressedTexImage2D's prototype"
)]
extern "C" fn gl_compressed_tex_image_2d(
    target: u32,
    level: i32,
    internal: u32,
    width: i32,
    height: i32,
    border: i32,
    size: i32,
    data: usize,
) {
    record(vec![
        uint(target),
        int(level),
        uint(internal),
        int(width),
        int(height),
        int(border),
        int(size),
        data as u64,
    ]);
}
extern "C" fn gl_get_path_length_nv(path: u32, start: i32, num: i32) -> f32 {
    record(vec![uint(path), int(start), int(num)]);
    PATH_LENGTH
}

/// One GL call of the fixture: check letter, GL name, the result class its prototype gives, the recorder, and the arguments fixture.c passes. In fixture.c `qg_table` order.
struct Call {
    letter: char,
    name: &'static str,
    ret: Class,
    recorder: usize,
    args: Vec<u64>,
}

fn calls() -> Vec<Call> {
    let call = |letter, name, ret, recorder: usize, args| Call {
        letter,
        name,
        ret,
        recorder,
        args,
    };
    vec![
        call(
            'c',
            "glClearColor",
            Class::Void,
            gl_clear_color as *const () as usize,
            vec![float(0.125), float(-2.5), float(0.0625), float(3.75)],
        ),
        call(
            'u',
            "glUniform4f",
            Class::Void,
            gl_uniform4f as *const () as usize,
            vec![
                int(-7),
                float(1.5),
                float(-0.25),
                float(1024.5),
                float(0.375),
            ],
        ),
        call(
            'd',
            "glDepthRangef",
            Class::Void,
            gl_depth_rangef as *const () as usize,
            vec![float(0.1875), float(0.8125)],
        ),
        call(
            't',
            "glTexParameterf",
            Class::Void,
            gl_tex_parameterf as *const () as usize,
            vec![
                uint(GL_TEXTURE_2D),
                uint(GL_TEXTURE_MIN_FILTER),
                float(GL_LINEAR as f32),
            ],
        ),
        call(
            'a',
            "glVertexAttrib4f",
            Class::Void,
            gl_vertex_attrib4f as *const () as usize,
            vec![uint(5), float(2.0), float(-3.0), float(4.5), float(-5.25)],
        ),
        call(
            'i',
            "glTexImage2D",
            Class::Void,
            gl_tex_image_2d as *const () as usize,
            vec![
                uint(GL_TEXTURE_2D),
                int(2),
                int(GL_RGBA as i32),
                int(64),
                int(32),
                int(0),
                uint(GL_RGBA),
                uint(GL_UNSIGNED_BYTE),
                TEX_PIXELS,
            ],
        ),
        call(
            'j',
            "glTexSubImage2D",
            Class::Void,
            gl_tex_sub_image_2d as *const () as usize,
            vec![
                uint(GL_TEXTURE_2D),
                int(1),
                int(3),
                int(5),
                int(16),
                int(8),
                uint(GL_RGB),
                uint(GL_UNSIGNED_SHORT_5_6_5),
                SUB_PIXELS,
            ],
        ),
        call(
            'k',
            "glCompressedTexImage2D",
            Class::Void,
            gl_compressed_tex_image_2d as *const () as usize,
            vec![
                uint(GL_TEXTURE_2D),
                int(0),
                uint(GL_ETC1_RGB8_OES),
                int(128),
                int(64),
                int(0),
                int(4096),
                ETC_DATA,
            ],
        ),
        call(
            'n',
            "glGetPathLengthNV",
            Class::Fp,
            gl_get_path_length_nv as *const () as usize,
            vec![uint(11), int(2), int(3)],
        ),
    ]
}

/// BOOT's payload: the fixture's entry table; identity, so the host reads it directly.
static TABLE: AtomicU64 = AtomicU64::new(0);

fn check(letter: char, result: Result<(), String>) -> bool {
    match result {
        Ok(()) => {
            println!("qemu-gl: ({letter}) ok");
            true
        }
        Err(why) => {
            println!("qemu-gl: ({letter}) FAIL {why}");
            false
        }
    }
}

/// BOOT records the table; the binding traps take the production route.
fn on_trap(trap: qemu::Trap) -> qemu::Answer {
    match trap {
        qemu::Trap::Boot(table) => {
            TABLE.store(table, Ordering::Relaxed);
            qemu::Answer::default()
        }
        other => qemu::on_trap(other),
    }
}

/// The result class of `name`'s row in the QEMU table, or why it has none.
fn row_class(name: &str) -> Result<Class, String> {
    match rows().find(|&(lib, n, _)| lib == SONAME && n == name) {
        Some((
            _,
            _,
            Binding::Generic {
                host: Host::System,
                ret,
                ..
            },
        )) => Ok(ret),
        Some((_, _, other)) => Err(format!(
            "{name}: row {other:?}, not a Generic System binding"
        )),
        None => Err(format!("{name}: no row in {SONAME}")),
    }
}

/// Binds each call's recorder by its row's class, runs the fixture's entry with that pool address, and checks the recorded words.
fn checks(table: u64) -> bool {
    let calls = calls();
    let mut ok = true;
    let mut bound = Vec::new();
    let mut bad_rows = Vec::new();
    for c in &calls {
        match row_class(c.name) {
            Ok(ret) if ret == c.ret => bound.push(Some(ret)),
            Ok(ret) => {
                bad_rows.push(format!(
                    "{}: class {ret:?}, prototype gives {:?}",
                    c.name, c.ret
                ));
                bound.push(None);
            }
            Err(e) => {
                bad_rows.push(e);
                bound.push(None);
            }
        }
    }
    ok &= check(
        'b',
        if bad_rows.is_empty() {
            Ok(())
        } else {
            Err(bad_rows.join("; "))
        },
    );
    for (i, (c, ret)) in calls.iter().zip(bound).enumerate() {
        let Some(ret) = ret else {
            ok &= check(c.letter, Err(format!("{}: not bound (check b)", c.name)));
            continue;
        };
        let Some(addr) = qemu::bind_result(c.recorder, ret) else {
            ok &= check(c.letter, Err("pool used up".to_owned()));
            continue;
        };
        // SAFETY: the table is the fixture's static array of nine entry pointers (`qg_table`), mapped in this process (identity).
        let entry = unsafe { (table as *const u64).add(i).read() };
        record(Vec::new());
        let returned = qemu::call(entry, &[addr as u64]);
        let seen = std::mem::take(&mut *SEEN.lock().expect("seen"));
        let mut why = Vec::new();
        if seen != c.args {
            why.push(format!("{} got {seen:x?}, want {:x?}", c.name, c.args));
        }
        let want_ret = if ret == Class::Fp {
            u64::from(PATH_LENGTH.to_bits())
        } else {
            0
        };
        if returned != want_ret {
            why.push(format!("the guest got {returned:#x}, want {want_ret:#x}"));
        }
        ok &= check(
            c.letter,
            if why.is_empty() {
                Ok(())
            } else {
                Err(why.join("; "))
            },
        );
    }
    ok
}

fn main() -> ExitCode {
    let (Some(so), Some(fixture)) = (
        std::env::var_os("ATL_ENGINE_SO"),
        std::env::var_os("ATL_QEMU_GL_FIXTURE"),
    ) else {
        println!("qemu-gl: SKIP (ATL_ENGINE_SO / ATL_QEMU_GL_FIXTURE unset)");
        return ExitCode::SUCCESS;
    };
    // the process's engine is QEMU before `boot` claims it, so `rows` reads the QEMU table
    if let Err(e) = engine::claim(Some(qemu::GUEST_ISA)) {
        println!("qemu-gl: (s) FAIL engine: {e}");
        return ExitCode::from(2);
    }
    if let Err(e) = qemu::boot(Path::new(&so), Path::new(&fixture), on_trap) {
        println!("qemu-gl: (s) FAIL boot: {e}");
        return ExitCode::from(2);
    }
    // the thunk pool the bindings hand out is host memory: registered so a guest fetch from it does not fault (no guest linker here to do it)
    if let Err(e) = qemu::attach_current().and_then(|()| qemu::register(&[])) {
        println!("qemu-gl: (s) FAIL attach: {e}");
        return ExitCode::from(2);
    }
    let table = TABLE.load(Ordering::Relaxed);
    if !check(
        's',
        if table == 0 {
            Err("BOOT carried no entry table".to_owned())
        } else {
            Ok(())
        },
    ) {
        return ExitCode::FAILURE;
    }
    if checks(table) {
        ExitCode::SUCCESS
    } else {
        ExitCode::FAILURE
    }
}
